<?php require __DIR__.'/../bootstrap.php'; require_admin(); $id=(int)($_GET['id']??0);$st=db()->prepare('SELECT * FROM bug_reports WHERE id=?');$st->execute([$id]);$r=$st->fetch();if(!$r){http_response_code(404);exit('Report not found');}$msg=flash(); ?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>#<?=$r['id']?> — IssuePilot</title><link rel="stylesheet" href="../assets/style.css"></head><body class="adminbody"><header class="adminnav"><a class="brand" href="dashboard.php"><span class="mark">↗</span> IssuePilot</a><div><a class="btn" href="dashboard.php">← All reports</a></div></header><main class="adminmain"><div class="adminhead"><div><h1>#<?=$r['id']?> · <?=e($r['title'])?></h1><div class="muted" style="margin-top:5px">Submitted <?=e(date('M j, Y · H:i',strtotime($r['created_at'])))?></div></div></div><?php if($msg):?><div class="notice"><?=e($msg)?></div><?php endif;?><div class="detailgrid"><section class="panel"><div class="detailsection"><h3>Description</h3><div class="detailtext"><?=e($r['description'])?></div></div><div class="detailsection"><h3>Steps to reproduce</h3><div class="detailtext"><?=e($r['steps'])?></div></div><div class="detailsection"><h3>Expected behavior</h3><div class="detailtext"><?=e($r['expected_behavior'])?></div></div><div class="detailsection"><h3>Actual behavior</h3><div class="detailtext"><?=e($r['actual_behavior'])?></div></div><?php if($r['attachment']):?><div class="detailsection"><h3>Screenshot</h3><a href="../<?=e($r['attachment'])?>" target="_blank"><img src="../<?=e($r['attachment'])?>" alt="Bug screenshot" style="max-width:100%;border:1px solid var(--line);border-radius:10px"></a></div><?php endif;?></section><aside><form class="panel" method="post" action="update.php"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="id" value="<?=$r['id']?>"><div class="field"><label>Status</label><select class="select" name="status"><?php foreach(['new','triaged','in_progress','resolved','closed'] as $s):?><option value="<?=$s?>" <?=$r['status']===$s?'selected':''?>><?=ucwords(str_replace('_',' ',$s))?></option><?php endforeach;?></select></div><div class="field"><label>Severity</label><select class="select" name="severity"><?php foreach(['low','medium','high','critical'] as $s):?><option value="<?=$s?>" <?=$r['severity']===$s?'selected':''?>><?=ucfirst($s)?></option><?php endforeach;?></select></div><div class="field"><label>Admin note</label><textarea class="textarea" name="admin_note" placeholder="Internal triage note"><?=e($r['admin_note'])?></textarea></div><button class="btn primary" style="width:100%">Save changes</button></form><form class="panel" style="margin-top:14px" method="post" action="delete.php" onsubmit="return confirm('Delete this report permanently?')"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn" style="width:100%;color:var(--danger)">Delete report</button></form><div class="panel" style="margin-top:14px"><h3>Reporter</h3><p class="muted" style="line-height:1.7"><?=e($r['reporter_name']?:'Anonymous')?><br><?=e($r['reporter_email']?:'No email provided')?><br><?=e($r['browser_device']?:'Environment not provided')?><br><?=e($r['page_url']?:'No page URL')?></p></div></aside></div></main></body></html>
